        [STAThread]
        static int Main()
        {
            string dir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "DoctorPc");
            try { Directory.CreateDirectory(dir); }
            catch (Exception ex) { MessageBox.Show("GRESKA: ne mogu da napravim folder\n" + dir + "\n\n" + ex.Message, "DoctorPc"); return 92; }

            string enginePath = Path.Combine(dir, "KiRo_PC_Diagnostic_Repair_v4_1_ENGINE.ps1");
            string guiPath    = Path.Combine(dir, "KiRo_PC_Diagnostic_Repair_v4_1_GUI.ps1");

            try
            {
                File.WriteAllBytes(enginePath, Convert.FromBase64String(EngineB64));
                File.WriteAllBytes(guiPath,    Convert.FromBase64String(GuiB64));
            }
            catch (Exception ex) { MessageBox.Show("GRESKA pri raspakivanju:\n\n" + ex.Message, "DoctorPc"); return 92; }

            if (Environment.GetEnvironmentVariable("DOCTORPC_EXTRACT_ONLY") == "1")
            {
                MessageBox.Show("Extract-only OK:\n" + dir, "DoctorPc");
                return 0;
            }

            string args = "-NoLogo -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"" + guiPath + "\"";
            if (Environment.GetEnvironmentVariable("DOCTORPC_TEST") == "1")
                args += " -NoElevate";

            try
            {
                Process p = Process.Start("powershell.exe", args);
                p.WaitForExit();
                return p.ExitCode;
            }
            catch (Exception ex)
            {
                MessageBox.Show("GRESKA pri pokretanju GUI-ja:\n\n" + ex.Message + "\n\nPokusajte rucno:\npowershell.exe " + args, "DoctorPc");
                return 1;
            }
        }
    }
